∀ {X Y A : Type u} (q : X → Y) (P : ℕ → X → A → PMF X) (n : ℕ) (S : Set X) (a : A) (y : Y),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.successorSupport q P n S a y =
    {x' | q x' = y ∧ ∃ x ∈ S, x' ∈ (P n x a).support}

