∀ {X Y : Type u} (p₀ : PMF X) (q : X → Y) (y : Y),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.initialSupport p₀ q y =
    {x | x ∈ p₀.support ∧ q x = y}

